                   for i in range(r, r + 5)
                   for j in range(c, c + 5)):
                seeds.append((r, c, color))

    # Join overlapping or touching seed windows of the same color, then
    # recolor their combined bounding rectangle.
    used = [False] * len(seeds)
    for k, (r, c, color) in enumerate(seeds):
        if used[k]:
            continue
        group = [(r, c)]
        used[k] = True
        changed = True
        while changed:
            changed = False
            r0 = min(x for x, y in group)
            r1 = max(x for x, y in group) + 4
            c0 = min(y for x, y in group)
